#include <assert.h>
#include <pthread.h>
#include <stdio.h>

enum { N = 5 };

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;
pthread_cond_t not_full = PTHREAD_COND_INITIALIZER;

int slot = -1;
int has_item = 0;
int consumed_sum = 0;

void* producer(void* arg) {
    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        while (has_item) {
            pthread_cond_wait(&not_full, &mutex);
        }
        slot = i;
        has_item = 1;
        printf("produce %d\n", i);
        pthread_cond_signal(&not_empty);
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void* consumer(void* arg) {
    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        while (!has_item) {
            pthread_cond_wait(&not_empty, &mutex);
        }
        int value = slot;
        has_item = 0;
        consumed_sum += value;
        printf("consume %d\n", value);
        pthread_cond_signal(&not_full);
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main(void) {
    setvbuf(stdout, NULL, _IONBF, 0);

    pthread_t p, c;
    assert(pthread_create(&p, NULL, producer, NULL) == 0);
    assert(pthread_create(&c, NULL, consumer, NULL) == 0);
    assert(pthread_join(p, NULL) == 0);
    assert(pthread_join(c, NULL) == 0);

    assert(consumed_sum == N * (N - 1) / 2);
    puts("all items consumed once");
    return 0;
}

#include <assert.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <unistd.h>

enum { MAX_CONCURRENT = 3, TOTAL_TASKS = 10 };

sem_t pool_slots;
int max_concurrent_seen = 0;
pthread_mutex_t stat_mutex = PTHREAD_MUTEX_INITIALIZER;

void* worker(void* arg) {
    int id = *(int*)arg;
    sem_wait(&pool_slots);  // 获取许可，不足则阻塞

    // 模拟占用连接
    pthread_mutex_lock(&stat_mutex);
    static int current = 0;
    current++;
    if (current > max_concurrent_seen) max_concurrent_seen = current;
    pthread_mutex_unlock(&stat_mutex);

    printf("task %d acquired slot (current=%d)\n", id, current);
    usleep(100000);  // 模拟 100ms 工作

    pthread_mutex_lock(&stat_mutex);
    current--;
    pthread_mutex_unlock(&stat_mutex);

    sem_post(&pool_slots);  // 释放许可，任意线程可释放
    return NULL;
}

int main(void) {
    sem_init(&pool_slots, 0, MAX_CONCURRENT);

    pthread_t threads[TOTAL_TASKS];
    int ids[TOTAL_TASKS];
    for (int i = 0; i < TOTAL_TASKS; i++) {
        ids[i] = i;
        pthread_create(&threads[i], NULL, worker, &ids[i]);
    }
    for (int i = 0; i < TOTAL_TASKS; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("max concurrent seen: %d (limit: %d)\n", max_concurrent_seen, MAX_CONCURRENT);
    assert(max_concurrent_seen <= MAX_CONCURRENT);
    puts("concurrency correctly bounded");
    sem_destroy(&pool_slots);
    return 0;
}
